def solution(signals):
    def lcm(a, b):
        def gcd(x, y):
            while y:
                x, y = y, x % y
            return x
        return a * b // gcd(a, b)

    def find_yellow_time(index, time):
        if index == len(signals):
            return time
        period = signals[index] * 3
        for t in range(time, period):
            if t % period < signals[index]:
                return find_yellow_time(index + 1, t)
        return -1

    total_period = 1
    for signal in signals:
        total_period = lcm(total_period, signal * 3)

    return find_yellow_time(0, 0) if total_period else -1

def solution(signals):
    from math import gcd
    from functools import reduce

    def lcm(a, b):
        return a * b // gcd(a, b)

    total_cycle = reduce(lcm, [signal[0] + signal[1] + signal[2] for signal in signals])

    for t in range(total_cycle):
        if all((t % (signal[0] + signal[1] + signal[2])) >= signal[0] and (t % (signal[0] + signal[1] + signal[2])) < (signal[0] + signal[1]) for signal in signals):
            return t

    return -1

