def solution(message, spoiler_ranges):
    from bisect import bisect_left, bisect_right

    n = len(message)
    spoiler = [0] * (n + 1)

    for start, end in spoiler_ranges:
        spoiler[start] += 1
        if end + 1 <= n:
            spoiler[end + 1] -= 1

    for i in range(1, n + 1):
        spoiler[i] += spoiler[i - 1]

    important_words = set()
    for i in range(n):
        if spoiler[i] == 0:
            important_words.add(message[i])

    return len(important_words)

