def solution(schedules, timelogs, startday):
    def count_employees(day_index, count):
        if day_index >= 7:
            return count
        if day_index in [5, 6]:
            return count_employees(day_index + 1, count)
        current_day = (startday + day_index) % 7
        for i in range(len(schedules)):
            if timelogs[i][current_day] <= schedules[i][current_day]:
                count += 1
        return count_employees(day_index + 1, count)

    return count_employees(0, 0)

def solution(video_len, pos, op_start, op_end, commands):
    def process_command(pos, command):
        if command == "prev":
            return max(0, pos - 10)
        elif command == "next":
            return min(video_len, pos + 10)
        elif command == "skip":
            return min(video_len, pos + 60)
        return pos

    pos = process_command(pos, commands[0])
    if len(commands) > 1:
        pos = process_command(pos, commands[1])
    if len(commands) > 2:
        pos = process_command(pos, commands[2])
