    if len(commands) > 5:
        pos = process_command(pos, commands[5])
    if len(commands) > 6:
        pos = process_command(pos, commands[6])
    if len(commands) > 7:
        pos = process_command(pos, commands[7])
    if len(commands) > 8:
        pos = process_command(pos, commands[8])
    if len(commands) > 9:
