        return pos
    command = commands[0]
    if command == "prev":
        pos = max(0, pos - 10)
    elif command == "next":
        pos = min(video_len, pos + 10)
    elif command == "skip":
        pos = op_end if pos < op_end else pos
    return solution(video_len, pos, op_start, op_end, commands[1:])

def solution(wallet, bill):
    def fold(bill):
        if (bill[0] <= wallet[0] and bill[1] <= wallet[1]) or (bill[1] <= wallet[0] and bill[0] <= wallet[1]):
            return 0
        if bill[0] > wallet[0]:
            return 1 + fold((bill[0] // 2, bill[1]))
        if bill[1] > wallet[1]:
            return 1 + fold((bill[0], bill[1] // 2))
    return fold(bill)

