        if index >= len(players):
            return -1
        if players[index] == name:
            return index
        return find_index(name, index + 1)

    def update_position(calling_index):
        if calling_index > 0:
            players[calling_index], players[calling_index - 1] = players[calling_index - 1], players[calling_index]
            update_position(calling_index - 1)

    for calling in callings:
        index = find_index(calling)
        if index != -1:
            update_position(index)

    return players

def solution(players, callings):
