    for calling in callings:
        idx = index_map[calling]
        if idx > 0:
            prev_player = players[idx - 1]
            players[idx], players[idx - 1] = players[idx - 1], players[idx]
            index_map[calling], index_map[prev_player] = idx - 1, idx
    return players

def solution(players, callings):
    def recursive_update(index):
        if index < 0 or index >= len(callings):
            return
        called_player = callings[index]
        player_index = players.index(called_player)
        if player_index > 0:
            players[player_index], players[player_index - 1] = players[player_index - 1], players[player_index]
            recursive_update(index + 1)

    recursive_update(0)
    return players

