def solution(park, routes):
    def move(x, y, direction, steps):
        if steps == 0:
            return x, y
        if direction == 'N':
            new_x, new_y = x - 1, y
        elif direction == 'S':
            new_x, new_y = x + 1, y
        elif direction == 'E':
            new_x, new_y = x, y + 1
        elif direction == 'W':
            new_x, new_y = x, y - 1

        if 0 <= new_x < len(park) and 0 <= new_y < len(park[0]) and park[new_x][new_y] != 'X':
            return move(new_x, new_y, direction, steps - 1)
        return x, y

    start_x, start_y = next((i, j) for i in range(len(park)) for j in range(len(park[0])) if park[i][j] == 'S')

    for route in routes:
        direction, steps = route.split()
        steps = int(steps)
        start_x, start_y = move(start_x, start_y, direction, steps)

    return [start_x, start_y]

def solution(park, routes):
    rows, cols = len(park), len(park[0])
    obstacles = set((r, c) for r in range(rows) for c in range(cols) if park[r][c] == 'X')
    start = next((r, c) for r in range(rows) for c in range(cols) if park[r][c] == 'O')
    directions = {'N': (-1, 0), 'S': (1, 0), 'E': (0, 1), 'W': (0, -1)}

    r, c = start
    for route in routes:
        dir, dist = route.split()
        dr, dc = directions[dir]
        for _ in range(int(dist)):
            if 0 <= r + dr < rows and 0 <= c + dc < cols and (r + dr, c + dc) not in obstacles:
                r += dr
                c += dc
            else:
                break
    return [r, c]

def solution(park, routes):
    def is_valid_move(x, y):
        return 0 <= x < len(park) and 0 <= y < len(park[0]) and park[x][y] != 'X'

    def move(x, y, route, index):
        if index >= len(route):
            return (x, y)
        direction, steps = route[index][0], int(route[index][1])
        dx, dy = (0, 1) if direction == 'E' else (0, -1) if direction == 'W' else (1, 0) if direction == 'S' else (-1, 0)

        for _ in range(steps):
            if is_valid_move(x + dx, y + dy):
                x += dx
                y += dy
            else:
                return (x, y)
        return move(x, y, route, index + 1)

    start_x, start_y = next((i, j) for i in range(len(park)) for j in range(len(park[0])) if park[i][j] == 'P')
    return move(start_x, start_y, routes, 0)

