def solution(m, n, startX, startY, balls):
    import heapq
    from collections import defaultdict

    def reflect(x, y, dx, dy):
        if dx == 1 and x == m: return (2 * m - x, y)
        if dx == -1 and x == 1: return (2 - x, y)
        if dy == 1 and y == n: return (x, 2 * n - y)
        if dy == -1 and y == 1: return (x, 2 - y)
        return (x + dx, y + dy)

    def dijkstra():
        distances = defaultdict(lambda: float('inf'))
        distances[(startX, startY)] = 0
        pq = [(0, startX, startY)]

        while pq:
            dist, x, y = heapq.heappop(pq)
            if dist > distances[(x, y)]:
                continue

            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = reflect(x, y, dx, dy)
                new_dist = dist + ((nx - x) ** 2 + (ny - y) ** 2) ** 0.5
                if new_dist < distances[(nx, ny)]:
                    distances[(nx, ny)] = new_dist
                    heapq.heappush(pq, (new_dist, nx, ny))

        return distances

    distances = dijkstra()
    return [distances[(bx, by)] for bx, by in balls]

