def solution(data, col, row_begin, row_end):
    def quicksort(arr, key_index):
        if len(arr) <= 1:
            return arr
        pivot = arr[len(arr) // 2]
        left = [x for x in arr if x[key_index] < pivot[key_index]]
        middle = [x for x in arr if x[key_index] == pivot[key_index]]
        right = [x for x in arr if x[key_index] > pivot[key_index]]
        return quicksort(left, key_index) + middle + quicksort(right, key_index)

    def calculate_hash_value(row):
        return sum(row[i] % (idx + 1) for idx, i in enumerate(row))

    data = quicksort(data, col - 1)
    hash_value = 0
    for i in range(row_begin - 1, row_end):
        hash_value ^= calculate_hash_value(data[i])
    return hash_value

def solution(data, col, row_begin, row_end):
    def recursive_sort(arr, col, start=0):
        if start >= len(arr) - 1:
            return arr
        for i in range(start, len(arr) - 1):
            if arr[i][col] > arr[i + 1][col] or (arr[i][col] == arr[i + 1][col] and arr[i][0] < arr[i + 1][0]):
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                return recursive_sort(arr, col, start)
        return arr

    def calculate_hash(arr, row_begin, row_end, index=0, hash_value=0):
        if index >= row_end - row_begin + 1:
            return hash_value
        S_i = sum(arr[row_begin - 1 + index]) % (index + 1)
        return calculate_hash(arr, row_begin, row_end, index + 1, hash_value ^ S_i)

    sorted_data = recursive_sort(data, col)
    return calculate_hash(sorted_data, row_begin, row_end)

